@sig trait RequestArbiter_Api {
  def id: Art.BridgeId
  def pilotRequest_Id : Art.PortId
  def chargerState_Id : Art.PortId
  def recoveryProposal_Id : Art.PortId
  def arbitratedIntent_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var arbitratedIntent: Drone_Lifecycle_Governor.ArbitratedIntent = $

  def put_arbitratedIntent(value : Drone_Lifecycle_Governor.ArbitratedIntent) : Unit = {
    Contract(
      Modifies(arbitratedIntent),
      Ensures(
        arbitratedIntent == value
      )
    )
    Spec {
      arbitratedIntent = value
    }

    Art.putValue(arbitratedIntent_Id, Drone_Lifecycle_Governor.ArbitratedIntent_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

